package codegen

import (
	"bufio"
	"errors"
	"fmt"
	"go/token"
	"io/fs"
	"os"
	"path/filepath"
	"regexp"
	"strconv"
	"strings"

	"github.com/kud360/goxsd8/xsd"
)

// fileName is the one file Generate writes into each Target's Dir.
const fileName = "xsd_gen.go"

// generatedHeader is the first line of every file Generate writes, in the
// form generatedLine recognizes.
const generatedHeader = "// Code generated by github.com/kud360/goxsd8/codegen. DO NOT EDIT."

// generatedLine is the Go convention's marker for a generated file. Generate
// overwrites an existing destination file only when its first line matches.
var generatedLine = regexp.MustCompile(`^// Code generated .* DO NOT EDIT\.$`)

// Target pairs one finalized schema with the package Generate emits for it. A
// field that breaks its rule below is a plain error before any write.
type Target struct {
	// Schema is the finalized schema to generate from. Generate requires it
	// non-nil; CheckTargets does not read it.
	Schema *xsd.Schema
	// Dir is the output directory, non-empty, resolved relative to the
	// process working directory when it is not absolute. It lies in a Go
	// module, and its import path is derived from that module: the module
	// path that the module directive of the nearest go.mod at or above Dir
	// made absolute declares, joined by "/" with Dir's slash-separated path
	// relative to that go.mod's directory, or the module path alone when Dir
	// is that directory. The walk up from Dir passes through every part of it
	// that does not exist yet. The path is not checked against the go
	// command's rules for import paths.
	Dir string
	// Package is the emitted package's name: a Go identifier that is neither a
	// keyword, the blank identifier, nor main.
	Package string
	// Name names the target in Generate's errors; it may be empty.
	Name string
}

// targetName is the name Generate's doc gives the target at slice index i
// whose Name is name.
func targetName(name string, i int) string {
	if name != "" {
		return name
	}
	return fmt.Sprintf("target %d", i)
}

// TargetError is one failure of one target, as Generate and CheckTargets
// report it.
type TargetError struct {
	index int
	name  string
	err   error
}

// Error returns the failure's text opened with the target's name, as
// Generate's doc states.
func (e *TargetError) Error() string {
	if e.name != "" {
		return e.name + ": " + e.err.Error()
	}
	return "codegen: " + targetName("", e.index) + ": " + e.err.Error()
}

// Index returns the failing target's index in the slice passed to Generate or
// CheckTargets.
func (e *TargetError) Index() int { return e.index }

// Unwrap returns the failure the target's name opens.
func (e *TargetError) Unwrap() error { return e.err }

// failed is err as Generate and CheckTargets return it for the target at slice
// index i, and the one construction site of a TargetError.
func (t Target) failed(i int, err error) *TargetError {
	return &TargetError{index: i, name: t.Name, err: err}
}

// Generate emits, for each target, one Go package of type declarations: the
// file xsd_gen.go in the target's Dir, declaring the types the package doc's
// "Coverage" states, in the order it states and named as "Naming" states. A
// target's Schema is its whole composed set, so its {element declarations}
// (§3.17.1), and with them its file's top-level types, include those of every
// imported or included document, the overriding declaration standing in for
// each one an <xs:override> replaces, and a Schema with none gives a file that
// declares no type.
//
// A target imports the declarations of a document it shares with an earlier
// target under the same nearest go.mod whose emitted declarations of it agree,
// and defines every other document's itself. Its package imports the package of
// each earlier target it imports a document from, by the import path
// Target.Dir's doc derives, and writes, in place of each declaration of that
// document, the alias type N = imp.N under the header that declaration carries.
// A target that imports nothing writes the file it would write alone.
//
// A declaration belongs to the document whose Loc its header renders
// ("Naming"); a datatype struct, PrecisionDecimal with its interface and arms, a
// raw-content struct, MixedChild, Nillable with its arms, and a variant of a
// builtin member render none and belong to no document. A target T imports a
// document D from the earliest target O before it whose nearest go.mod
// (Target.Dir) lies in the same directory as T's, that defines D itself and
// agrees with T on D: the declarations T and O emit for D are the same text,
// and so are the declarations each set reaches, transitively: through the type
// names its text names, a sealed interface reaching each declaration carrying
// its marker method and an arm its interface, and the type of a nillable
// top-level declaration whose nilled value is Nillable over it reaching
// Nillable; every text is compared with its header's Loc as the Loc carries it,
// so independent of Dir.
//
// Each document that closure reaches must then be taken by T from the package O
// takes it from, and Generate withdraws the imports that break this until none
// does.
//
// The import name imp is O's Package unless that name is taken, and otherwise
// that name followed by the smallest numeric suffix from 2 that is not. A name
// is taken when it is a Go predeclared identifier, big, the name of one of T's
// own top-level types, aliases included, or the import name of an earlier owner
// in slice order.
//
// A document that agrees with no earlier target defining it under the same
// nearest go.mod, or breaks the closure condition, the target defines itself
// exactly as it would alone; two targets whose emitted declarations of a shared
// document differ, in a name or in a shape, each declare its types, and one URI
// composed into different components, as a chameleon include is, renders
// different declarations and is never shared. A target that imports a document
// writes a declaration belonging to no document only when one of its own
// definitions reaches it, reaching read as agreement reads it above.
//
// The file is gofmt-formatted. Generate writes no go.mod and adds no
// //go:generate line: the module the caller puts Dir in owns both.
//
// Generate runs in two phases. Phase 1 checks every target and builds its
// source in memory, in slice order; phase 2 writes. A target that fails phase
// 1 — a nil Schema, a refusal CheckTargets reports, or a construct the
// generator declines — means no target is written. Phase 1 collects every
// decline, in target order, and stops at the first failure that is not a
// decline, which follows the declines collected before it. Within one target a
// nil Schema comes first, then its refusal, either of which ends phase 1 before
// its declines; then its declines, in walk order — each top-level element
// declaration in document order, depth first through the types its particles
// reach (the package doc's "Coverage") — at most one for each top-level element
// declaration, whose walk ends at its first decline. A decline with the same
// Construct and the same text as one already collected for the target is
// collected once, where first met, whatever meets it again.
//
// Two particles refine that walk order: a local element whose type is already
// emitted, and an <element ref>. A local element that occurs exactly once and
// whose type, not a choice, is already emitted has that type checked again,
// through such elements, for a type reaching itself, and the decline
// "Particles" states for one found there precedes every decline the depth-first
// walk meets after that element. The walk does not enter the type of the
// top-level declaration an <element ref> particle names, which that
// declaration's own turn emits. A ref to a declaration not yet reached checks
// that declaration's properties and the shape of its type where the ref is met
// — for a declaration given a sealed interface over its governing types, the
// shape of each complex type among them, its simple ones checked at its own
// turn. A ref to a substitution-group head given an interface checks so each
// declaration of its group with {abstract} false, in group order. Any other
// ref that occurs exactly once to a complex type that is not a choice has that
// type checked there, in the same way, for an element or type reaching itself,
// ahead of every decline the depth-first walk meets after the ref.
//
// Generate returns nil when it writes every target, and otherwise one
// *TargetError per failure, in that order, a phase-2 fault alone; each opens
// with the failing target's name: its Name, or "target N" for the target at
// slice index N when Name is empty. An unnamed target's error opens "codegen:
// target N: ", a named one's "<Name>: " with no "codegen: " before it. The
// refusal of a Dir equal to an earlier target's Dir, and that of a Dir whose
// import path equals an earlier target's, open with the failing target's name
// like every other error, and their text names that earlier target too: by its
// Name, or "target N" for its slice index N when Name is empty, with no
// "codegen: " before it. A *TargetError's Index method returns N, and it
// unwraps to the failure the opening precedes.
//
// A decline is a generator refusal, not a schema fault: it is a
// *DeclineError, never an *xsderr.Error, and it wraps errors.ErrUnsupported,
// so errors.Is(e, errors.ErrUnsupported) reports an element e that holds a
// decline, and errors.As(e, &de) retrieves that element's *DeclineError. Its
// Construct method returns the construct declined, and its Loc method the Loc
// that method's doc states. Its text names both; the opening with the target's
// name, stated above, precedes that text and is no part of it. The package
// doc's "Coverage" section states what the generator accepts.
//
// Phase 2 creates Dir and its parents when absent. An existing xsd_gen.go is
// overwritten only when its first line matches `^// Code generated .* DO NOT
// EDIT\.$`; otherwise phase 1 fails. Generate never deletes a file and never
// touches another file in Dir. An I/O failure during phase 2 is the only
// failure that can leave some targets written and others not.
func Generate(targets []Target) []*TargetError {
	var errs []*TargetError
	units := make([]*unit, len(targets))
	for i, t := range targets {
		u, declines, err := prepare(t, targets[:i])
		for _, d := range declines {
			errs = append(errs, t.failed(i, d))
		}
		if err != nil {
			return append(errs, t.failed(i, err))
		}
		units[i] = u
	}
	if len(errs) > 0 {
		return errs
	}
	for i, t := range targets {
		if err := link(units, i); err != nil {
			return []*TargetError{t.failed(i, err)}
		}
	}
	for i, t := range targets {
		if err := os.MkdirAll(t.Dir, 0o755); err != nil {
			return []*TargetError{t.failed(i, fmt.Errorf("creating %s: %w", t.Dir, err))}
		}
		path := filepath.Join(t.Dir, fileName)
		if err := os.WriteFile(path, units[i].src, 0o644); err != nil {
			return []*TargetError{t.failed(i, fmt.Errorf("writing %s: %w", path, err))}
		}
	}
	return nil
}

// prepare is phase 1 for one target before link: it checks t's Schema, then
// checkTarget against the targets before it, then returns emit's declines
// and failure, or the unit of its declarations, so a nil Schema or a refusal,
// returned as err, precedes and suppresses the target's declines.
func prepare(t Target, earlier []Target) (u *unit, declines []*DeclineError, err error) {
	if t.Schema == nil {
		return nil, nil, errors.New("the Schema field is nil")
	}
	base, mod, path, err := checkTarget(t, earlier)
	if err != nil {
		return nil, nil, err
	}
	decls, declines, err := emit(t.Schema)
	if err != nil || len(declines) > 0 {
		return nil, declines, err
	}
	u, err = newUnit(t.Package, base, mod, path, decls)
	return u, nil, err
}

// CheckTargets reports, without reading any Schema and without writing, the
// targets Generate refuses whatever their Schemas hold. It returns nil when no
// target is refused, and otherwise one *TargetError per refused target, in
// slice order, the first of its refusals below, opened with the target's name
// as Generate's are. A target is refused, in this order, when its Dir or
// Package breaks its field's rule; when its Dir equals an earlier target's
// non-empty Dir after filepath.Clean, the earlier target refused or not; when
// filepath.Abs cannot make its Dir absolute; and when its Dir exists and is not a
// directory, or holds an xsd_gen.go that is not a regular file or that Generate's
// overwrite rule does not let it replace, or either cannot be checked or read;
// when no go.mod lies in its Dir or any directory above it; when the nearest
// one cannot be checked or read, or holds no module directive; and when the
// import path Dir's doc derives for it equals the one derived for an earlier
// target, the earlier target refused or not. Generate states how the
// duplicate-Dir and duplicate-import-path refusals name the earlier target,
// and the overwrite rule.
func CheckTargets(targets []Target) []*TargetError {
	var errs []*TargetError
	for i, t := range targets {
		if _, _, _, err := checkTarget(t, targets[:i]); err != nil {
			errs = append(errs, t.failed(i, err))
		}
	}
	return errs
}

// checkTarget is the one encoding of the refusals CheckTargets' doc lists, in
// that order, for t against the targets before it. It reads no Schema and
// returns Dir made absolute, the directory of the nearest go.mod at or above
// it, and the import path Dir's doc derives.
func checkTarget(t Target, earlier []Target) (base, mod, path string, err error) {
	if t.Dir == "" {
		return "", "", "", errors.New("no output directory given")
	}
	if token.IsKeyword(t.Package) {
		return "", "", "", fmt.Errorf("the package name %q is a Go keyword", t.Package)
	}
	if t.Package == "_" {
		return "", "", "", errors.New(`the package name "_" is the blank identifier`)
	}
	if !token.IsIdentifier(t.Package) {
		return "", "", "", fmt.Errorf("the package name %q is not a Go identifier", t.Package)
	}
	if t.Package == "main" {
		return "", "", "", errors.New(`the package name is "main", but the emitted package declares no func main and would not build`)
	}
	for j, e := range earlier {
		if e.Dir != "" && filepath.Clean(e.Dir) == filepath.Clean(t.Dir) {
			return "", "", "", fmt.Errorf("the output directory %s is also the output directory of %s", t.Dir, targetName(e.Name, j))
		}
	}
	base, err = filepath.Abs(t.Dir)
	if err != nil {
		return "", "", "", fmt.Errorf("resolving the output directory %s: %w", t.Dir, err)
	}
	if err := checkDestination(t.Dir); err != nil {
		return "", "", "", err
	}
	mod, path, err = importPath(t.Dir, base)
	if err != nil {
		return "", "", "", err
	}
	for j, e := range earlier {
		if earlierPath, ok := derivedPath(e.Dir); ok && earlierPath == path {
			return "", "", "", fmt.Errorf("the output directory %s has the import path %s, which is also the import path of %s", t.Dir, path, targetName(e.Name, j))
		}
	}
	return base, mod, path, nil
}

// derivedPath is the import path Target.Dir's doc derives for dir, false when
// dir is empty or the derivation fails.
func derivedPath(dir string) (string, bool) {
	if dir == "" {
		return "", false
	}
	base, err := filepath.Abs(dir)
	if err != nil {
		return "", false
	}
	_, path, err := importPath(dir, base)
	return path, err == nil
}

// importPath derives the import path Target.Dir's doc states for the output
// directory dir, base being dir made absolute: it walks from base up to the
// filesystem root, passing through each directory holding no go.mod, and
// reads the first go.mod it meets (modulePackage). It returns the directory
// holding that go.mod, absolute and cleaned, no symbolic link resolved, then
// the path.
func importPath(dir, base string) (string, string, error) {
	for mod := base; ; {
		gomod := filepath.Join(mod, "go.mod")
		_, err := os.Stat(gomod)
		if err == nil {
			path, err := modulePackage(gomod, mod, base)
			return mod, path, err
		}
		if !errors.Is(err, fs.ErrNotExist) {
			return "", "", fmt.Errorf("checking %s: %w", gomod, err)
		}
		parent := filepath.Dir(mod)
		if parent == mod {
			return "", "", fmt.Errorf("no go.mod lies in the output directory %s or any directory above it, so it has no import path", dir)
		}
		mod = parent
	}
}

// modulePackage returns the import path of the absolute directory base in
// the module whose go.mod, at gomod, lies in mod, base itself or one of its
// ancestors.
func modulePackage(gomod, mod, base string) (string, error) {
	data, err := os.ReadFile(gomod)
	if err != nil {
		return "", fmt.Errorf("reading %s: %w", gomod, err)
	}
	module, ok := moduleDirective(string(data))
	if !ok {
		return "", fmt.Errorf("%s holds no module directive", gomod)
	}
	rel, err := filepath.Rel(mod, base)
	if err != nil {
		return "", fmt.Errorf("resolving %s against %s: %w", base, mod, err)
	}
	if rel == "." {
		return module, nil
	}
	return module + "/" + filepath.ToSlash(rel), nil
}

// moduleDirective returns the module path that the first line of the go.mod
// content data whose first word is module declares, false when there is no
// such line or it declares none. It declares one when it holds the word
// module, then the path, bare or as a Go string literal, holding no white
// space and no //, then at most a // comment; the block form module ( ... )
// declares none.
func moduleDirective(data string) (string, bool) {
	for _, line := range strings.Split(data, "\n") {
		line, _, _ = strings.Cut(line, "//")
		fields := strings.Fields(line)
		if len(fields) == 0 || fields[0] != "module" {
			continue
		}
		if len(fields) != 2 || fields[1] == "(" {
			return "", false
		}
		path := fields[1]
		if path[0] != '"' && path[0] != '`' {
			return path, true
		}
		unquoted, err := strconv.Unquote(path)
		if err != nil || unquoted == "" {
			return "", false
		}
		return unquoted, true
	}
	return "", false
}

// checkDestination fails unless phase 2 may write xsd_gen.go into dir: dir is
// absent or a directory, and the file is absent or a regular file whose first
// line marks it generated.
func checkDestination(dir string) error {
	info, err := os.Stat(dir)
	if errors.Is(err, fs.ErrNotExist) {
		return nil
	}
	if err != nil {
		return fmt.Errorf("checking %s: %w", dir, err)
	}
	if !info.IsDir() {
		return fmt.Errorf("the output directory %s exists and is not a directory", dir)
	}
	path := filepath.Join(dir, fileName)
	info, err = os.Lstat(path)
	if errors.Is(err, fs.ErrNotExist) {
		return nil
	}
	if err != nil {
		return fmt.Errorf("checking %s: %w", path, err)
	}
	if !info.Mode().IsRegular() {
		return fmt.Errorf("%s exists and is not a regular file", path)
	}
	generated, err := isGenerated(path)
	if err != nil {
		return err
	}
	if !generated {
		return fmt.Errorf("%s exists and its first line does not mark it generated, so it is never overwritten", path)
	}
	return nil
}

// isGenerated reports whether the first line of the file at path matches
// generatedLine. A first line longer than bufio.Scanner's default token limit
// reads as not generated.
func isGenerated(path string) (generated bool, err error) {
	f, err := os.Open(path)
	if err != nil {
		return false, fmt.Errorf("checking %s: %w", path, err)
	}
	defer func() {
		if cerr := f.Close(); cerr != nil && err == nil {
			err = fmt.Errorf("closing %s: %w", path, cerr)
		}
	}()
	s := bufio.NewScanner(f)
	if !s.Scan() {
		if serr := s.Err(); serr != nil && !errors.Is(serr, bufio.ErrTooLong) {
			return false, fmt.Errorf("reading %s: %w", path, serr)
		}
		return false, nil
	}
	return generatedLine.MatchString(s.Text()), nil
}
